808	package com.loja.services;
809	
810	import com.loja.api.PaymentRequest;
811	import com.loja.models.Enums;
812	import com.loja.models.Order;
813	import com.loja.models.OrderItem;
814	
815	import java.sql.SQLException;
816	import java.time.Instant;
817	
818	public class PaymentService {
819	    private static final long PAYMENT_TIMEOUT_MS = 48 * 60 * 60 * 1000;
820	
821	    public static class PaymentResult {
822	        public String error;
823	        public int httpStatus;
824	        public Order order;
825	        public boolean success;
826	
827	        public PaymentResult(String error, int httpStatus) {
828	            this.error = error;
829	            this.httpStatus = httpStatus;
830	            this.success = false;
831	        }
832	
833	        public PaymentResult(Order order) {
834	            this.order = order;
835	            this.success = true;
836	        }
837	    }
838	
839	    public static PaymentResult processPayment(String orderId, PaymentRequest paymentReq) throws SQLException {
840	        Order order = OrderService.getOrder(orderId);
841	        if (order == null) {
842	            return new PaymentResult("ORDER_NOT_FOUND", 404);
843	        }
844	
845	        if (paymentReq.transactionId == null || paymentReq.transactionId.isEmpty() ||
846	            paymentReq.paidAt == null || paymentReq.paidAt.isEmpty()) {
847	            return new PaymentResult("INVALID_ORDER", 422);
848	        }
849	
850	        if (order.status != Enums.OrderStatus.AWAITING_PAYMENT) {
851	            if (OrderService.isPaymentDuplicate(orderId, paymentReq.transactionId)) {
852	                return new PaymentResult(order);
853	            }
854	            return new PaymentResult("OPERATION_NOT_ALLOWED", 409);
855	        }
856	
857	        Instant paidAt = Instant.parse(paymentReq.paidAt);
858	        Instant createdAt = order.createdAt;
859	        long timeDiffMs = paidAt.toEpochMilli() - createdAt.toEpochMilli();
860	
861	        if (timeDiffMs > PAYMENT_TIMEOUT_MS) {
862	            OrderService.updateOrderStatus(orderId, Enums.OrderStatus.CANCELLED);
863	            String cpf = OrderService.getCustomerCpf(orderId);
864	            NotificationService.createNotification(cpf, Enums.NotificationType.ORDER_CANCELLED, orderId);
865	            return new PaymentResult("ORDER_EXPIRED", 409);
866	        }
867	
868	        for (OrderItem item : order.items) {
869	            if (ProductService.getProduct(item.sku).stock < item.quantity) {
870	                OrderService.updateOrderStatus(orderId, Enums.OrderStatus.CANCELLED);
871	                String cpf = OrderService.getCustomerCpf(orderId);
872	                NotificationService.createNotification(cpf, Enums.NotificationType.ORDER_CANCELLED, orderId);
873	                return new PaymentResult("INSUFFICIENT_STOCK", 409);
874	            }
875	        }
876	
877	        for (OrderItem item : order.items) {
878	            ProductService.updateStock(item.sku, -item.quantity);
879	        }
880	
881	        String cpf = OrderService.getCustomerCpf(orderId);
882	        CustomerService.updateCreditBalance(cpf, order.summary.nextPurchaseCredit);
883	
884	        OrderService.recordPayment(orderId, paymentReq.transactionId, paidAt);
885	        OrderService.updateOrderStatus(orderId, Enums.OrderStatus.PAID);
886	
887	        NotificationService.createNotification(cpf, Enums.NotificationType.PAYMENT_APPROVED, orderId);
888	
889	        return new PaymentResult(OrderService.getOrder(orderId));
890	    }
891	}
