import java.math.*; import java.net.http.*; import java.net.URI; import java.util.*;
public class Ref {
  static BigDecimal r(BigDecimal v){ return v.setScale(2, RoundingMode.HALF_EVEN); }
  static Map<String,BigDecimal> P = Map.of("CAM-001",new BigDecimal("79.90"),"TEN-001",new BigDecimal("249.90"),"FON-001",new BigDecimal("199.90"),"MEI-001",new BigDecimal("19.90"),"JAQ-001",new BigDecimal("389.90"));
  public static void main(String[] a) throws Exception {
    HttpClient c = HttpClient.newHttpClient();
    String[] regions={"SOUTHEAST","SOUTH","MIDWEST","NORTH","NORTHEAST"};
    String[][] pays={{"PIX","1"},{"CREDIT_CARD","2"},{"CREDIT_CARD","3"},{"CREDIT_CARD","5"},{"CREDIT_CARD","12"},{"BANK_SLIP","1"}};
    String[] skus={"CAM-001","MEI-001","FON-001","TEN-001"};
    int n=0, bad=0; Map<String,Integer> badField=new TreeMap<>(); List<String> samples=new ArrayList<>();
    for (int q1=1;q1<=3;q1++) for (int q2=0;q2<=3;q2++) for (String s2: new String[]{"MEI-001","FON-001","TEN-001"}) for (String reg: regions) for (String[] pay: pays) {
      if (q2==0 && !s2.equals("MEI-001")) continue;
      BigDecimal sub = P.get("CAM-001").multiply(BigDecimal.valueOf(q1));
      String items="[{\"sku\":\"CAM-001\",\"quantity\":"+q1+"}";
      if (q2>0){ sub=sub.add(P.get(s2).multiply(BigDecimal.valueOf(q2))); items+=",{\"sku\":\""+s2+"\",\"quantity\":"+q2+"}"; }
      items+="]";
      BigDecimal pct = switch(reg){case "SOUTHEAST","SOUTH"->new BigDecimal("0.01"); case "MIDWEST"->new BigDecimal("0.015"); case "NORTH"->new BigDecimal("0.025"); default->new BigDecimal("0.02");};
      BigDecimal ins=r(sub.multiply(pct)); if ((reg.equals("NORTH")||reg.equals("NORTHEAST")) && ins.compareTo(new BigDecimal("30"))>0) ins=new BigDecimal("30.00");
      BigDecimal total=r(sub.add(ins)); int inst=Integer.parseInt(pay[1]);
      BigDecimal fin, instAmt, adj;
      if (pay[0].equals("PIX")){ BigDecimal d=r(total.multiply(new BigDecimal("0.05"))); fin=total.subtract(d); instAmt=fin; }
      else if (pay[0].equals("BANK_SLIP")){ fin=total.add(new BigDecimal("3.49")); instAmt=fin; if (fin.compareTo(new BigDecimal("1000"))>0 && total.compareTo(new BigDecimal("1000"))>0) continue; }
      else if (inst<=3){ fin=total; instAmt=total.divide(BigDecimal.valueOf(inst),2,RoundingMode.HALF_EVEN); }
      else { MathContext mc=new MathContext(40); BigDecimal i=new BigDecimal("0.0199"); BigDecimal f=BigDecimal.ONE.divide(BigDecimal.ONE.add(i).pow(inst,mc),mc); instAmt=r(total.multiply(i).divide(BigDecimal.ONE.subtract(f),mc)); fin=instAmt.multiply(BigDecimal.valueOf(inst)); }
      adj=fin.subtract(total);
      if (pay[0].equals("BANK_SLIP") && total.compareTo(new BigDecimal("1000"))>0) continue;
      String body="{\"customer\":{\"cpf\":\"30000000001\",\"email\":\"a@b.com\"},\"items\":"+items+",\"zipCode\":\"01310100\",\"region\":\""+reg+"\",\"shippingMethod\":\"STORE_PICKUP\",\"paymentMethod\":\""+pay[0]+"\",\"installments\":"+inst+",\"clubTier\":\"BRONZE\"}";
      HttpResponse<String> res=c.send(HttpRequest.newBuilder(URI.create("http://localhost:8081/checkout/summary")).header("Content-Type","application/json").POST(HttpRequest.BodyPublishers.ofString(body)).build(), HttpResponse.BodyHandlers.ofString());
      n++;
      String s=res.body();
      Map<String,BigDecimal> exp=new LinkedHashMap<>(); exp.put("productsSubtotal",sub); exp.put("insurance",ins); exp.put("paymentAdjustment",adj); exp.put("finalTotal",fin); exp.put("installmentAmount",instAmt);
      boolean ok=res.statusCode()==200; List<String> diffs=new ArrayList<>();
      if(!ok) diffs.add("status "+res.statusCode()+" "+s);
      else for (var e: exp.entrySet()){ java.util.regex.Matcher m=java.util.regex.Pattern.compile("\""+e.getKey()+"\":(-?[0-9.E]+)").matcher(s); m.find(); BigDecimal got=new BigDecimal(m.group(1)); if (got.compareTo(e.getValue())!=0){ diffs.add(e.getKey()+" exp "+e.getValue()+" got "+got); badField.merge(e.getKey(),1,Integer::sum);} }
      if(!diffs.isEmpty()){ bad++; if (samples.size()<25) samples.add(items+" "+reg+" "+pay[0]+"x"+inst+" -> "+diffs); }
    }
    System.out.println("calls="+n+" mismatching="+bad+" byField="+badField);
    samples.forEach(System.out::println);
  }
}
