      String body="{\"customer\":{\"cpf\":\"30000000001\",\"email\":\"a@b.com\"},\"items\":"+items+",\"zipCode\":\"01310100\",\"region\":\""+reg+"\",\"shippingMethod\":\"STORE_PICKUP\",\"paymentMethod\":\""+pay[0]+"\",\"installments\":"+inst+",\"clubTier\":\"BRONZE\"}";
      HttpResponse<String> res=c.send(HttpRequest.newBuilder(URI.create("http://localhost:8081/checkout/summary")).header("Content-Type","application/json").POST(HttpRequest.BodyPublishers.ofString(body)).build(), HttpResponse.BodyHandlers.ofString());
      n++;
      String s=res.body();
      Map<String,BigDecimal> exp=new LinkedHashMap<>(); exp.put("productsSubtotal",sub); exp.put("insurance",ins); exp.put("paymentAdjustment",adj); exp.put("finalTotal",fin); exp.put("installmentAmount",instAmt);
      boolean ok=res.statusCode()==200; List<String> diffs=new ArrayList<>();
      if(!ok) diffs.add("status "+res.statusCode()+" "+s);
      else for (var e: exp.entrySet()){ java.util.regex.Matcher m=java.util.regex.Pattern.compile("\""+e.getKey()+"\":(-?[0-9.E]+)").matcher(s); m.find(); BigDecimal got=new BigDecimal(m.group(1)); if (got.compareTo(e.getValue())!=0){ diffs.add(e.getKey()+" exp "+e.getValue()+" got "+got); badField.merge(e.getKey(),1,Integer::sum);} }
      if(!diffs.isEmpty()){ bad++; if (samples.size()<25) samples.add(items+" "+reg+" "+pay[0]+"x"+inst+" -> "+diffs); }
    }
    System.out.println("calls="+n+" mismatching="+bad+" byField="+badField);
    samples.forEach(System.out::println);
  }
}
