import java.nio.file.*;
import java.util.concurrent.atomic.AtomicInteger;

public class Stub {
    static AtomicInteger CNT = new AtomicInteger();
    // mode file: body | "SLOW <ms> <body>" | "STATUS <code> <body>" | "SEQ m1 ;; m2 ;; ..."
    public static void main(String[] a) throws Exception {
        HttpServer s = HttpServer.create(new InetSocketAddress(9999), 0);
        s.setExecutor(java.util.concurrent.Executors.newCachedThreadPool());
        s.createContext("/reset", ex -> { CNT.set(0); ex.sendResponseHeaders(200, -1); ex.close(); });
        s.createContext("/", ex -> {
            String q = ex.getRequestURI().toString();
            Files.writeString(Path.of("/tmp/stub/log"), q + "\n", StandardOpenOption.CREATE, StandardOpenOption.APPEND);
            String mode = Files.readString(Path.of("/tmp/stub/mode")).trim();
            if (mode.startsWith("SEQ ")) { String[] p = mode.substring(4).split(";;"); mode = p[Math.min(CNT.getAndIncrement(), p.length - 1)].trim(); }
            int code = 200; String body = mode;
            try {
                if (mode.startsWith("SLOW ")) { String[] p = mode.split(" ", 3); Thread.sleep(Long.parseLong(p[1])); body = p[2]; }
                else if (mode.startsWith("STATUS ")) { String[] p = mode.split(" ", 3); code = Integer.parseInt(p[1]); body = p[2]; }
            } catch (InterruptedException e) {}
            byte[] b = body.getBytes();
            ex.getResponseHeaders().add("Content-Type", "application/json");
            ex.sendResponseHeaders(code, b.length);
            ex.getResponseBody().write(b); ex.close();
        });
        s.start();
        System.out.println("stub up");
    }
}
